import './holding-import.css';
import { escapeHtml, instrumentLabel, money } from './format';
import { buildHoldingReview, duplicateImageReceipt, validateHoldingObservationDate, type HoldingRecognition, type HoldingReviewRow } from './holding-import';
import { confirmPortfolio, type PositionInput } from './portfolio-ledger';
import { savePortfolio, saveRecoveryPoint } from './store';
import type { HoldingImportReceipt, LocalPortfolio, PublicSnapshot } from './types';

interface HoldingImportOptions {
  root: string;
  snapshot: PublicSnapshot;
  portfolio: LocalPortfolio;
  trigger?: HTMLElement | null;
  onCancel?: () => void;
  onSaved: (portfolio: LocalPortfolio, announcement: string) => void;
}

function amountLabel(mode: 'QUANTITY' | 'MARKET_VALUE', amount: number): string {
  return mode === 'QUANTITY' ? `${amount.toLocaleString('zh-CN')} 份` : money(amount);
}

function reviewRowsMarkup(rows: HoldingReviewRow[], firstSetup: boolean): string {
  return rows.map((row) => {
    const status = !row.recognized ? '截图中未出现' : row.needsReview ? '需要核对' : row.changed ? '发生变化' : '已识别';
    const tone = row.needsReview ? 'warning' : row.changed ? 'changed' : row.recognized ? 'matched' : 'omitted';
    const warnings = row.warnings.length ? `<small>${escapeHtml(row.warnings.join('；'))}</small>` : '';
    const review = row.needsReview ? `<label class="ocr-confirm"><input type="checkbox" name="review-${row.code}" required><span>${!row.recognized && firstSetup ? '我确认当前未持有，按零持仓建立' : '我已对照截图核对'}</span></label>` : '';
    const cost = firstSetup && row.recognized && row.proposedMode === 'QUANTITY'
      ? `<label class="ocr-cost"><span>首次单位成本（可选）</span><input name="cost-${row.code}" type="number" min="0" step="0.0001" value="${row.unitCost ?? ''}" placeholder="不知道可留空"></label>` : '';
    const evidenceLabel = row.confidence == null ? '' : row.needsReview ? ' · 识别不确定' : ' · 字段完整';
    return `<article class="ocr-review-row ${tone}" data-ocr-row="${row.code}"><header><div><strong>${escapeHtml(instrumentLabel(row.code, row.name))}</strong><small>${escapeHtml(status)}${evidenceLabel}</small></div><span>${row.changed ? '需确认' : '保持'}</span></header><div class="ocr-value-compare"><span><small>当前保存</small><strong>${amountLabel(row.currentMode, row.currentAmount)}</strong></span><i>→</i><label><small>拟保存</small><span class="ocr-proposed-input"><select name="mode-${row.code}" aria-label="${escapeHtml(row.name)}输入方式"><option value="QUANTITY" ${row.proposedMode === 'QUANTITY' ? 'selected' : ''}>份额</option><option value="MARKET_VALUE" ${row.proposedMode === 'MARKET_VALUE' ? 'selected' : ''}>市值</option></select><input name="amount-${row.code}" type="number" min="0" step="0.01" value="${row.proposedAmount}" ${row.recognized ? '' : 'readonly'}></span></label></div>${warnings}${review}${cost}</article>`;
  }).join('');
}

function dialogMarkup(): string {
  return `<dialog id="holding-import-dialog" class="holding-import-dialog" aria-labelledby="holding-import-title"><form id="holding-import-form"><header class="dialog-head"><div><p>本机识别 · 不连接券商</p><h2 id="holding-import-title">导入持仓截图</h2></div><button type="button" data-close-holding-import aria-label="关闭">×</button></header>
    <p class="privacy">图片仅在当前设备中识别，不上传服务器、不保存原图或 OCR 全文。只有你核对并确认后的结构化持仓会写入当前浏览器。</p>
    <section class="holding-import-step active" data-import-step="select"><div class="ocr-dropzone" data-ocr-dropzone><span>01</span><h3>拖入或选择持仓截图</h3><p>支持 PNG、JPEG、WebP，最多 3 张。建议先遮挡姓名、账号和资产账号。</p><button type="button" class="primary" data-select-holding-images>选择图片</button><input id="holding-image-input" type="file" accept="image/png,image/jpeg,image/webp" multiple hidden><small data-file-summary>尚未选择图片</small></div><div class="dialog-actions"><button type="button" class="secondary" data-close-holding-import>取消</button><button type="button" class="primary" data-start-holding-ocr disabled>开始本机识别</button></div></section>
    <section class="holding-import-step" data-import-step="progress" hidden><div class="ocr-progress" role="status" aria-live="polite"><span class="ocr-spinner" aria-hidden="true"></span><h3>正在准备本机识别</h3><p data-ocr-progress>读取模型与图片，不会上传。</p></div><div class="dialog-actions"><button type="button" class="secondary" data-cancel-holding-ocr>取消识别</button></div></section>
    <section class="holding-import-step" data-import-step="review" hidden><div class="ocr-review-head"><div><p class="eyebrow">02 · 人工核对</p><h3 data-review-title>核对识别结果</h3><p data-review-summary></p></div><div class="ocr-review-meta"><label><span>截图日期</span><input name="observedAt" type="date" required></label><label><span>组合内现金</span><input name="cash" type="number" min="0" step="0.01" required></label><label class="ocr-confirm cash-confirm"><input type="checkbox" name="cashConfirmed" required><span>我确认这是组合内现金，不是购买力或总资产</span></label></div></div><div class="ocr-global-warnings" data-ocr-warnings></div><div class="ocr-review-list" data-ocr-review-list></div><div class="impact-preview"><strong>确认后</strong><span>会更新：真实持仓、现金、快照与脱敏回执</span><span>不会改变：风险分数、模型目标、已有成本与交易历史</span></div><div class="dialog-status" data-import-status tabindex="-1" aria-live="polite"></div><div class="dialog-actions"><button type="button" class="secondary" data-back-to-images>返回换图</button><button type="submit" class="primary">确认并更新真实持仓</button></div></section>
  </form></dialog>`;
}

function showStep(dialog: HTMLDialogElement, step: 'select' | 'progress' | 'review'): void {
  dialog.querySelectorAll<HTMLElement>('[data-import-step]').forEach((section) => {
    const active = section.dataset.importStep === step;
    section.hidden = !active;
    section.classList.toggle('active', active);
  });
}

export function openHoldingImport(options: HoldingImportOptions): void {
  document.querySelector('#holding-import-dialog')?.remove();
  document.body.insertAdjacentHTML('beforeend', dialogMarkup());
  const dialog = document.querySelector<HTMLDialogElement>('#holding-import-dialog');
  const form = document.querySelector<HTMLFormElement>('#holding-import-form');
  const input = document.querySelector<HTMLInputElement>('#holding-image-input');
  if (!dialog || !form || !input) return;
  let selectedFiles: File[] = [];
  let recognition: HoldingRecognition | null = null;
  let fingerprints: string[] = [];
  let rows: HoldingReviewRow[] = [];
  let abortController: AbortController | null = null;
  let completed = false;

  const close = (): void => {
    abortController?.abort();
    dialog.close();
  };
  dialog.querySelectorAll<HTMLElement>('[data-close-holding-import]').forEach((button) => button.addEventListener('click', close));
  dialog.addEventListener('close', () => {
    dialog.remove();
    if (!completed && options.onCancel) options.onCancel();
    else requestAnimationFrame(() => options.trigger?.focus({ preventScroll: true }));
  });
  const setFiles = (files: File[]): void => {
    selectedFiles = files.slice(0, 3);
    const summary = dialog.querySelector<HTMLElement>('[data-file-summary]');
    const start = dialog.querySelector<HTMLButtonElement>('[data-start-holding-ocr]');
    if (summary) summary.textContent = selectedFiles.length ? `已选择 ${selectedFiles.length} 张 · ${selectedFiles.map((file) => file.name || '相机图片').join('、')}` : '尚未选择图片';
    if (start) start.disabled = selectedFiles.length === 0;
  };
  dialog.querySelector('[data-select-holding-images]')?.addEventListener('click', () => input.click());
  input.addEventListener('change', () => setFiles([...input.files ?? []]));
  const dropzone = dialog.querySelector<HTMLElement>('[data-ocr-dropzone]');
  ['dragenter', 'dragover'].forEach((type) => dropzone?.addEventListener(type, (event) => { event.preventDefault(); dropzone.classList.add('dragging'); }));
  ['dragleave', 'drop'].forEach((type) => dropzone?.addEventListener(type, (event) => { event.preventDefault(); dropzone.classList.remove('dragging'); }));
  dropzone?.addEventListener('drop', (event) => setFiles([...event.dataTransfer?.files ?? []]));
  dialog.querySelector('[data-start-holding-ocr]')?.addEventListener('click', async () => {
    const progress = dialog.querySelector<HTMLElement>('[data-ocr-progress]');
    try {
      showStep(dialog, 'progress');
      abortController = new AbortController();
      const { recognizeHoldingImages, validateHoldingImages } = await import('./ocr-engine');
      validateHoldingImages(selectedFiles);
      const result = await recognizeHoldingImages(selectedFiles, options.root, (state) => {
        if (progress) progress.textContent = `${state.stage === 'PREPARING' ? '正在预处理' : '正在读取'}第 ${state.fileIndex}/${state.fileCount} 张图片`;
      }, abortController.signal);
      recognition = result.recognition;
      fingerprints = result.fingerprints;
      const duplicate = duplicateImageReceipt(fingerprints, options.portfolio.holdingImportReceipts);
      if (duplicate) throw new Error(`这些图片已于 ${duplicate.createdAt.slice(0, 10)} 确认导入，请勿重复保存`);
      rows = buildHoldingReview(recognition, options.portfolio, options.snapshot.assets);
      const list = dialog.querySelector<HTMLElement>('[data-ocr-review-list]');
      const summary = dialog.querySelector<HTMLElement>('[data-review-summary]');
      const title = dialog.querySelector<HTMLElement>('[data-review-title]');
      const warnings = dialog.querySelector<HTMLElement>('[data-ocr-warnings]');
      const changed = rows.filter((row) => row.changed).length;
      const needsReview = rows.filter((row) => row.needsReview).length;
      if (list) list.innerHTML = reviewRowsMarkup(rows, !options.portfolio.baseline);
      if (title) title.textContent = `已识别 ${recognition.rows.length} 只策略标的`;
      if (summary) summary.textContent = `${changed} 项发生变化；${needsReview} 项必须对照截图确认。未出现的标的保持原值。`;
      if (warnings) warnings.innerHTML = recognition.warnings.map((warning) => `<p>${escapeHtml(warning)}</p>`).join('');
      const cash = form.elements.namedItem('cash') as HTMLInputElement;
      cash.value = String(recognition.cash ?? options.portfolio.cash);
      const observedAt = form.elements.namedItem('observedAt') as HTMLInputElement;
      observedAt.value = recognition.statementDate ?? new Date().toISOString().slice(0, 10);
      showStep(dialog, 'review');
      dialog.querySelector<HTMLInputElement>('[name^="review-"]')?.focus();
    } catch (error) {
      if ((error as DOMException)?.name === 'AbortError') { showStep(dialog, 'select'); return; }
      showStep(dialog, 'select');
      const summary = dialog.querySelector<HTMLElement>('[data-file-summary]');
      if (summary) summary.textContent = error instanceof Error ? error.message : String(error);
    } finally { abortController = null; }
  });
  dialog.querySelector('[data-cancel-holding-ocr]')?.addEventListener('click', () => { abortController?.abort(); showStep(dialog, 'select'); });
  dialog.querySelector('[data-back-to-images]')?.addEventListener('click', () => showStep(dialog, 'select'));
  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    const status = dialog.querySelector<HTMLElement>('[data-import-status]');
    try {
      if (!recognition || !rows.length) throw new Error('请先完成图片识别');
      if (!form.reportValidity()) return;
      const data = new FormData(form);
      const now = new Date().toISOString();
      const observedAt = validateHoldingObservationDate(String(data.get('observedAt') ?? ''), options.portfolio, now.slice(0, 10));
      const inputs = rows.map((row): PositionInput => {
        const inputMode = data.get(`mode-${row.code}`) === 'QUANTITY' ? 'QUANTITY' : 'MARKET_VALUE';
        const amount = Number(data.get(`amount-${row.code}`));
        if (!Number.isFinite(amount) || amount < 0) throw new Error(`${row.code}拟保存数值无效`);
        const rawCost = String(data.get(`cost-${row.code}`) ?? '').trim();
        const unitCost = rawCost ? Number(rawCost) : null;
        return !options.portfolio.baseline && inputMode === 'QUANTITY' && amount > 0 && unitCost != null
          ? { code: row.code, inputMode, amount, remainingCostBasis: amount * unitCost, costBasisSource: 'OPENING_LEDGER', costBasisStatus: 'COMPLETE', openingUnitCost: unitCost, openingDate: now.slice(0, 10), openingFee: 0, openingNote: '持仓截图识别后人工确认' }
          : { code: row.code, inputMode, amount };
      });
      const cash = Number(data.get('cash'));
      if (!Number.isFinite(cash) || cash < 0) throw new Error('组合内现金无效');
      const recovery = await saveRecoveryPoint(options.portfolio, now, 'BEFORE_IMAGE_IMPORT');
      let next = confirmPortfolio(options.portfolio, inputs, options.snapshot.assets, cash, now, undefined, 'IMAGE_REVIEW_CONFIRMED');
      const snapshotRecord = [...(next.snapshots ?? [])].reverse().find((item) => !item.supersededBy && item.createdAt === now);
      if (!snapshotRecord) throw new Error('未能建立图片确认快照，已取消保存');
      const receipt: HoldingImportReceipt = {
        id: `holding-import-${now.replace(/\D/g, '').slice(0, 17)}`,
        createdAt: now,
        observedAt,
        source: 'LOCAL_IMAGE_OCR',
        fileCount: selectedFiles.length,
        imageFingerprints: fingerprints,
        recognizedCodes: recognition.rows.map((row) => row.code),
        unchangedCodes: rows.filter((row) => !row.changed).map((row) => row.code),
        omittedCodes: rows.filter((row) => !row.recognized).map((row) => row.code),
        warningCodes: rows.filter((row) => row.needsReview).map((row) => row.code),
        snapshotId: snapshotRecord.id,
        confirmedValues: Object.fromEntries(inputs.map((input) => [input.code, { inputMode: input.inputMode, amount: input.amount }])),
        cashConfirmed: data.get('cashConfirmed') === 'on',
      };
      next = {
        ...next,
        holdingImportReceipts: [...(next.holdingImportReceipts ?? []), receipt],
        backupHealth: {
          ...(next.backupHealth ?? { status: 'UNTESTED', lastExportAt: null, lastRestoreDryRunAt: null, message: '尚未进行备份恢复校验' }),
          lastRecoveryPointId: recovery.id,
          lastRecoveryPointAt: recovery.createdAt,
        },
      };
      await savePortfolio(next);
      selectedFiles = [];
      recognition = null;
      completed = true;
      dialog.close();
      options.onSaved(next, `持仓截图已在本机识别并由你确认；保存 ${receipt.recognizedCodes.length} 只标的，${receipt.omittedCodes.length} 只未出现标的保持原值。`);
    } catch (error) {
      if (status) { status.textContent = error instanceof Error ? error.message : String(error); status.focus(); }
    }
  });
  dialog.showModal();
  requestAnimationFrame(() => dialog.querySelector<HTMLButtonElement>('[data-select-holding-images]')?.focus());
}
