import { ASSET_CODES, type AssetCode, type LocalPortfolio, type PositionInputMode, type PublicAsset } from './types';

const ASSET_ALIASES: Record<AssetCode, string[]> = {
  '510300': ['沪深300ETF', '沪深300', '300ETF'],
  '512890': ['红利低波ETF', '红利低波', '红利低波动'],
  '513500': ['标普500ETF', '标普ETF', '标普500', 'S&P500'],
  '513100': ['纳指ETF', '纳斯达克ETF', '纳指100', '纳斯达克100'],
  '588000': ['科创50ETF', '科创50', '科创板50'],
  '518880': ['黄金ETF', '黄金基金', '黄金'],
  '511010': ['国债ETF', '国债基金', '国债'],
};

export interface RecognizedHolding {
  code: AssetCode;
  nameMatched: string | null;
  quantity: number | null;
  marketValue: number | null;
  unitCost: number | null;
  confidence: number;
  evidence: string;
  warnings: string[];
  duplicate: boolean;
}

export interface HoldingRecognition {
  rows: RecognizedHolding[];
  cash: number | null;
  statementDate: string | null;
  warnings: string[];
}

export interface HoldingReviewRow {
  code: AssetCode;
  name: string;
  currentMode: PositionInputMode;
  currentAmount: number;
  proposedMode: PositionInputMode;
  proposedAmount: number;
  recognized: boolean;
  changed: boolean;
  needsReview: boolean;
  confidence: number | null;
  warnings: string[];
  unitCost: number | null;
}

function normalizeText(value: string): string {
  return value.normalize('NFKC')
    .replace(/[，]/g, ',')
    .replace(/[：]/g, ':')
    .replace(/[（]/g, '(')
    .replace(/[）]/g, ')')
    .replace(/[|｜]/g, ' ')
    .replace(/[ \t]+/g, ' ')
    .trim();
}

function parseNumber(value: string): number | null {
  const normalized = value.replace(/,/g, '').trim();
  const match = normalized.match(/^(-?\d+(?:\.\d+)?)(万|亿)?$/);
  if (!match) return null;
  const number = Number(match[1]);
  if (!Number.isFinite(number)) return null;
  return number * (match[2] === '万' ? 10_000 : match[2] === '亿' ? 100_000_000 : 1);
}

function labelledNumber(text: string, labels: string[]): number | null {
  for (const label of labels) {
    const match = text.match(new RegExp(`${label}\\s*[:：]?\\s*(-?[\\d,]+(?:\\.\\d+)?(?:万|亿)?)`, 'i'));
    const value = match?.[1] ? parseNumber(match[1]) : null;
    if (value != null) return value;
  }
  return null;
}

function numericTokens(text: string, code: AssetCode): number[] {
  const numericSource = ASSET_ALIASES[code].reduce(
    (source, alias) => source.replace(new RegExp(alias.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'gi'), ' '),
    text.replace(new RegExp(code, 'g'), ' '),
  );
  return [...numericSource.matchAll(/-?[\d,]+(?:\.\d+)?(?:万|亿)?/g)]
    .map((match) => match[0])
    .filter((token) => !numericSource.slice(Math.max(0, numericSource.indexOf(token) - 1), numericSource.indexOf(token) + token.length + 1).includes('%'))
    .map(parseNumber)
    .filter((value): value is number => value != null && value >= 0);
}

function assetMatch(line: string): { code: AssetCode; alias: string | null } | null {
  const exact = ASSET_CODES.find((code) => new RegExp(`(^|\\D)${code}(\\D|$)`).test(line));
  if (exact) return { code: exact, alias: ASSET_ALIASES[exact].find((alias) => line.toUpperCase().includes(alias.toUpperCase())) ?? null };
  for (const code of ASSET_CODES) {
    const alias = ASSET_ALIASES[code].find((candidate) => line.toUpperCase().includes(candidate.toUpperCase()));
    if (alias) return { code, alias };
  }
  return null;
}

function parseCandidate(code: AssetCode, alias: string | null, evidence: string): RecognizedHolding {
  const quantityLabelled = labelledNumber(evidence, ['持仓数量', '证券数量', '持有份额', '持仓份额', '持仓', '数量', '份额']);
  const labelledMarketValue = labelledNumber(evidence, ['参考市值', '最新市值', '证券市值', '持仓市值', '市值']);
  const labelledUnitCost = labelledNumber(evidence, ['成本价', '摊薄成本', '持仓成本价', '单位成本']);
  const tokens = numericTokens(evidence, code);
  const quantity = quantityLabelled ?? tokens.find((value) => Number.isInteger(value) && value >= 0) ?? null;
  const quantityIndex = quantity == null ? -1 : tokens.indexOf(quantity);
  const structuredColumns = quantityIndex >= 0 && tokens.length >= quantityIndex + 3;
  const unitCost = labelledUnitCost ?? (structuredColumns ? tokens[quantityIndex + 1] ?? null : null);
  const marketValue = labelledMarketValue ?? (structuredColumns ? tokens[quantityIndex + 2] ?? null : null);
  const matchedAlias = alias ?? ASSET_ALIASES[code].find((candidate) => evidence.toUpperCase().includes(candidate.toUpperCase())) ?? null;
  const warnings: string[] = [];
  if (quantity == null && marketValue == null) warnings.push('未能可靠识别份额或市值');
  if (quantity != null && !Number.isInteger(quantity)) warnings.push('份额不是整数，请核对');
  let confidence = 0.48;
  if (new RegExp(`(^|\\D)${code}(\\D|$)`).test(evidence)) confidence += 0.22;
  if (matchedAlias) confidence += 0.1;
  if (quantityLabelled != null || labelledMarketValue != null || structuredColumns) confidence += 0.15;
  if (unitCost != null) confidence += 0.05;
  confidence = Math.min(1, confidence);
  if (confidence < 0.9) warnings.push('识别可信度较低，必须人工核对');
  return { code, nameMatched: matchedAlias, quantity, marketValue, unitCost, confidence, evidence, warnings, duplicate: false };
}

/** Pure parser: accepts OCR text but never stores it. */
export function parseHoldingText(rawText: string): HoldingRecognition {
  const lines = rawText.split(/\r?\n/).map(normalizeText).filter(Boolean);
  const candidates: RecognizedHolding[] = [];
  const explicitCodes = new Set<AssetCode>(ASSET_CODES.filter((code) => lines.some((line) => new RegExp(`(^|\\D)${code}(\\D|$)`).test(line))));
  lines.forEach((line, index) => {
    const match = assetMatch(line);
    if (!match) return;
    const hasExactCode = new RegExp(`(^|\\D)${match.code}(\\D|$)`).test(line);
    if (!hasExactCode && explicitCodes.has(match.code)) return;
    const continuation: string[] = [line];
    for (let cursor = index + 1; cursor < Math.min(lines.length, index + 6); cursor += 1) {
      const next = lines[cursor]!;
      const nextCode = ASSET_CODES.find((code) => new RegExp(`(^|\\D)${code}(\\D|$)`).test(next));
      if (nextCode && nextCode !== match.code) break;
      continuation.push(next);
    }
    const evidence = continuation.join(' ');
    candidates.push(parseCandidate(match.code, match.alias, evidence));
  });

  const byCode = new Map<AssetCode, RecognizedHolding[]>();
  candidates.forEach((candidate) => byCode.set(candidate.code, [...(byCode.get(candidate.code) ?? []), candidate]));
  const rows = [...byCode.entries()].map(([, matches]) => {
    const best = [...matches].sort((left, right) => right.confidence - left.confidence)[0]!;
    const duplicate = matches.length > 1;
    return duplicate
      ? { ...best, duplicate: true, warnings: [...best.warnings, `同一标的识别到 ${matches.length} 行，请确认是否为重复截图`] }
      : best;
  });
  const normalized = normalizeText(rawText);
  const cash = labelledNumber(normalized, ['可用资金', '资金余额', '可取资金', '现金余额', '组合内现金']);
  const dateMatch = normalized.match(/(20\d{2})[-/.年](\d{1,2})[-/.月](\d{1,2})日?/);
  const statementDate = dateMatch
    ? `${dateMatch[1]}-${dateMatch[2]!.padStart(2, '0')}-${dateMatch[3]!.padStart(2, '0')}`
    : null;
  const warnings: string[] = [];
  if (!rows.length) warnings.push('没有识别到本组合的七只 ETF');
  if (rows.length < ASSET_CODES.length) warnings.push(`截图只覆盖 ${rows.length} 只策略标的；未出现的标的将保持原值`);
  if (cash == null) warnings.push('未识别组合内现金，将保持原值');
  return { rows, cash, statementDate, warnings };
}

export function mergeRecognitions(recognitions: HoldingRecognition[]): HoldingRecognition {
  const grouped = new Map<AssetCode, RecognizedHolding[]>();
  recognitions.flatMap((item) => item.rows).forEach((row) => grouped.set(row.code, [...(grouped.get(row.code) ?? []), row]));
  const rows = [...grouped.entries()].map(([, matches]) => {
    const best = [...matches].sort((left, right) => right.confidence - left.confidence)[0]!;
    if (matches.length === 1) return best;
    const values = new Set(matches.map((row) => `${row.quantity ?? ''}|${row.marketValue ?? ''}`));
    return {
      ...best,
      duplicate: true,
      warnings: [...best.warnings, values.size > 1 ? '多张截图对同一标的给出不同结果' : '多张截图包含同一标的，请确认没有重复'],
    };
  });
  return {
    rows,
    cash: recognitions.map((item) => item.cash).find((value) => value != null) ?? null,
    statementDate: recognitions.map((item) => item.statementDate).filter((value): value is string => Boolean(value)).sort().at(-1) ?? null,
    warnings: [...new Set(recognitions.flatMap((item) => item.warnings))],
  };
}

export function buildHoldingReview(
  recognition: HoldingRecognition,
  portfolio: LocalPortfolio,
  assets: PublicAsset[],
): HoldingReviewRow[] {
  return assets.map((asset) => {
    const current = portfolio.positionsByCode?.[asset.code];
    const currentMode = current?.inputMode ?? 'MARKET_VALUE';
    const currentAmount = currentMode === 'QUANTITY' ? current?.quantity ?? 0 : current?.confirmedMarketValue ?? portfolio.values[asset.code] ?? 0;
    const found = recognition.rows.find((row) => row.code === asset.code);
    const proposedMode: PositionInputMode = found?.quantity != null ? 'QUANTITY' : found?.marketValue != null ? 'MARKET_VALUE' : currentMode;
    const proposedAmount = found?.quantity ?? found?.marketValue ?? currentAmount;
    const changed = proposedMode !== currentMode || Math.abs(proposedAmount - currentAmount) > 1e-8;
    const firstSetupOmission = !portfolio.baseline && !found;
    const warnings = found?.warnings ?? [firstSetupOmission ? '截图中未出现，首次建账必须确认当前为零持仓' : '截图中未出现，将保持当前值'];
    return {
      code: asset.code,
      name: asset.name,
      currentMode,
      currentAmount,
      proposedMode,
      proposedAmount,
      recognized: Boolean(found),
      changed,
      needsReview: firstSetupOmission || Boolean(found && (found.confidence < 0.9 || found.duplicate || found.quantity == null && found.marketValue == null)),
      confidence: found?.confidence ?? null,
      warnings,
      unitCost: found?.unitCost ?? null,
    };
  });
}

export function duplicateImageReceipt(
  fingerprints: string[],
  receipts: Array<{ imageFingerprints: string[]; createdAt: string }> = [],
): { createdAt: string } | null {
  const key = [...fingerprints].sort().join('|');
  return receipts.find((receipt) => [...receipt.imageFingerprints].sort().join('|') === key) ?? null;
}

export function validateHoldingObservationDate(value: string, portfolio: LocalPortfolio, today: string): string {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value) || Number.isNaN(Date.parse(`${value}T00:00:00Z`))) throw new Error('请确认有效的截图日期');
  if (value > today) throw new Error('截图日期不能晚于今天');
  const latest = (portfolio.snapshots ?? []).filter((item) => !item.supersededBy).map((item) => item.asOf).sort().at(-1);
  if (latest && value < latest) throw new Error(`截图日期早于最近持仓快照 ${latest}，请使用更新的截图`);
  return value;
}
